// 🧠 Get AI draft
let aiContent = $input.first().json.finalDraft || "";

// 🧠 Get original articles (with linkLabel)
const articles = $("Code in JavaScript").all().map(i => i.json);

// 🔥 FIX LINKS DYNAMICALLY
articles.forEach(article => {
  if (!article.url) return;

  const label = article.linkLabel || "Read More";

  // Replace anchor text for matching URL
  const regex = new RegExp(
    `<a[^>]*href=["']${article.url}["'][^>]*>.*?<\\/a>`,
    "gi"
  );

  aiContent = aiContent.replace(
    regex,
    `<a href="${article.url}" style="color:#F26C2E;text-decoration:none;font-weight:bold;">${label}</a>`
  );
});

// 🎨 Style content
const styledContent = aiContent
  .replace(/<h2>/g, '<h2 style="margin:30px 0 10px 0;font-size:20px;">')
  .replace(/<p>/g, '<p style="color:#444;line-height:1.6;margin:10px 0;">')
  .replace(/<ul>/g, '<ul style="padding-left:18px;color:#444;">')
  .replace(/<li>/g, '<li style="margin-bottom:6px;">')
  .replace(/<a /g, '<a style="color:#F26C2E;text-decoration:none;font-weight:bold;" ');

// 📦 Final template
const template = `
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f5f5;">
<tr>
<td align="center">
<table width="600" cellpadding="20" cellspacing="0" style="background:#ffffff;font-family:Arial,sans-serif;">

<tr>
<td style="background:#F26C2E;height:6px;padding:0;"></td>
</tr>

<tr>
<td>
${styledContent}
</td>
</tr>

<tr>
<td align="center">
<a href="https://elegantfrontend.training"
style="display:inline-block;padding:12px 20px;background:#F26C2E;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:bold;">
Explore More on Elegant Frontend
</a>
</td>
</tr>

<tr>
<td style="font-size:12px;color:#888;text-align:center;">
You're receiving this because you subscribed at elegantfrontend.training
</td>
</tr>

</table>
</td>
</tr>
</table>
`;

return [{ json: { html: template } }];

const draft = $json.originalDraft;

const evaluationPrompt = `
You are a senior technical editor.

Evaluate the following newsletter draft on a scale of 1 to 10.

Criteria:
- Clarity
- Insight depth
- Professional tone
- Non-generic writing
- Actionability

Return STRICT JSON only:

{
  "score": number,
  "feedback": "short explanation"
}

Newsletter draft:
${draft}
`;

return [{
  json: {
    prompt: evaluationPrompt,
    originalDraft: draft
  }
}];

const draft = $input.first().json.response;

return [{
  json: {
    originalDraft: draft
  }
}];

// 1. Get the raw response and clean up special characters
let raw = $input.first().json.response || "";

// Remove markdown blocks and normalize whitespace/newlines
raw = raw.replace(/```json/g, "")
         .replace(/```/g, "")
         .replace(/\n/g, " ") 
         .trim();

let evaluation = { score: 0, feedback: "Parsing failed" };

try {
  evaluation = JSON.parse(raw);
} catch (e) {
  // Regex fallback if JSON is still malformed
  const scoreMatch = raw.match(/"score":\s*(\d+)/);
  if (scoreMatch) {
    evaluation.score = parseInt(scoreMatch[1]);
    evaluation.feedback = "Extracted via fallback (JSON format error)";
  }
}

// 2. Safely grab the original draft from the input
const originalDraft = $input.first().json.originalDraft || "";

return [{
  json: {
    approved: (evaluation.score || 0) >= 8,
    score: evaluation.score || 0,
    feedback: evaluation.feedback || "Review required",
    originalDraft: originalDraft,
    retryCount: 0
  }
}];

const draft = $json.originalDraft;
const feedback = $json.feedback;

const refinePrompt = `
You are a senior technical editor.

Improve the following newsletter based on this feedback:

Feedback:
${feedback}

Original Draft:
${draft}

Make it sharper, more insight-driven, and less generic.
Return ONLY improved HTML.
`;

return [{
  json: {
    prompt: refinePrompt
  }
}];

const improvedDraft = $input.first().json.response;

return [{
  json: {
    finalDraft: improvedDraft,
    wasRefined: true
  }
}];

return [{
  json: {
    response: $json.response,
    originalDraft: $node["Code in JavaScript9"].json.originalDraft
  }
}];

// Grab the HTML directly from your template node to be safe
const html = $node["Code in JavaScript8"].json.html || "";

const plainText = html
  .replace(/<h1>/g, "*")
  .replace(/<\/h1>/g, "*\n")
  .replace(/<h2>/g, "\n\n*")
  .replace(/<\/h2>/g, "*\n")
  .replace(/<[^>]+>/g, "")
  .substring(0, 1200);

// Fallback message if something goes wrong
const finalMessage = plainText.trim().length > 0 ? plainText : "Newsletter draft generated but preview is unavailable.";

return [{
  json: {
    text: "Frontend Weekly Draft",
    blocks: [
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: finalMessage
        }
      }
    ]
  }
}];

let linkedinPost = $json.response || "LinkedIn post generation failed.";

if (!linkedinPost.includes("#frontend")) {
  linkedinPost += "\n\n#frontend #webdev #ai";
}

return [{
  json: {
    linkedin_post: linkedinPost,
    finalDraft: $node["Merge1"].json.finalDraft,
    wasRefined: $node["Merge1"].json.wasRefined,
    slack_preview: {
      text: "LinkedIn Post Draft",
      blocks: [
        {
          type: "header",
          text: {
            type: "plain_text",
            text: "LinkedIn Post Draft"
          }
        },
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: `*LinkedIn Post Draft*\n\n${linkedinPost}`
          }
        }
      ]
    }
  }
}];

const linkedinPost = $json.linkedin_post || "No LinkedIn post available.";

return [{
  json: {
    text: "LinkedIn Draft",
    blocks: [
      {
        type: "header",
        text: {
          type: "plain_text",
          text: "LinkedIn Post Draft"
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: linkedinPost
        }
      }
    ]
  }
}];
